// 请求调度：优先级队列（高优先级先发，同优先级 FIFO）+ 最大并发限制
function createScheduler(maxConcurrent) {
  const waiting = [];
  const active = [];
  const finished = [];
  let seq = 0;
  let peak = 0;
  function admit() {
    while (active.length < maxConcurrent && waiting.length) {
      waiting.sort((a, b) => (b.priority - a.priority) || (a.seq - b.seq));
      active.push(waiting.shift());
    }
    peak = Math.max(peak, active.length);
  }
  return {
    enqueue(id, priority) { waiting.push({ id, priority, seq: seq++ }); return this; },
    admit,
    completeOne() {
      if (active.length === 0) return null;
      const job = active.shift();
      finished.push(job.id);
      admit();                     // 完成后立刻补位（保持打满并发）
      return job.id;
    },
    get peak() { return peak; },
    get active() { return active.length; },
    get waiting() { return waiting.length; },
  };
}

const s = createScheduler(2);
[['a', 1], ['b', 5], ['c', 3], ['d', 5], ['e', 2]].forEach(([id, p]) => s.enqueue(id, p));
s.admit();
console.log('peak_after_admit=' + s.peak);
console.log('active_after_admit=' + s.active);
console.log('waiting_after_admit=' + s.waiting);
const first = s.completeOne();
console.log('first_completed=' + first);
console.log('peak_never_exceeds_limit=' + (s.peak <= 2));

const done = [first];
while (s.waiting > 0 || s.active > 0) {
  const id = s.completeOne();
  if (id === null) break;
  done.push(id);
}
console.log('all_finished=' + done.join(','));
console.log('total_completed=' + done.length);
console.log('max_concurrency_respected=' + (s.peak <= 2));
